import { MEAL_TYPES, dateAndTimeToInstant, inStoreItemCode, nowHHMM, uuidv7, type FoodItem, type LabelReadResult, type LineInput, type MealType, type NewFoodItem } from '@motivation/shared';
import { fillFromLabel, readLabelPhoto, unreadLabels } from '../../../utils/label-read.js';
import { clearAiEstimateDraft, readAiEstimateDraft, saveAiEstimateDraft } from './estimate-draft.js';
import { HealthService } from '../../../services/health.service.js';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import { exitFlow, navigate } from '../../../router.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import { bindPickedBarcode } from '../../../utils/bind-picked-barcode.js';
import { whileBusy } from '../../../utils/in-flight.js';
import { foodLineView, ingredientView, newFoodLineView, toLineInput, type LineView } from '../../../utils/line-view.js';
import { defaultAmount, pickedLine } from '../../../utils/pick-line.js';
import { resolveScannedBarcode, type ScanResolution } from '../nutrition/food-picker/food-search-pipeline.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import {
    HEALTH_EVENTS,
    type BindConsentChangeEvent,
    type FoodEditorSaveEvent,
    type FoodPickActionEvent,
    type FoodPickEvent,
    type LinePickedEvent,
    type LineSetSaveEvent,
} from '../health-events.js';
import '../barcode-binding-banner.component.js';
import '../nutrition/food-picker/food-picker.component.js';
import '../nutrition/line-set-editor/line-set-editor.component.js';
import '../nutrition/line-add-dialog/line-add-dialog.component.js';
import '../nutrition/food-editor/food-editor.component.js';
import '../photo-controls/photo-controls.component.js';
import type { FoodEditor } from '../nutrition/food-editor/food-editor.component.js';
import type { PhotoControls } from '../photo-controls/photo-controls.component.js';
import type { FoodPicker } from '../nutrition/food-picker/food-picker.component.js';
import type { LineSetEditor } from '../nutrition/line-set-editor/line-set-editor.component.js';
import type { LineAddDialog } from '../nutrition/line-add-dialog/line-add-dialog.component.js';
import themeStyles from '../health-theme.css?inline';
import bindingStyles from '../barcode-binding.css?inline';
import screenStyles from './health-log-new-screen.css?inline';

/**
 * Story 432 — what the picker's scan resolved a code to, handed across the navigation to
 * `?barcode=` so the line opens without a second lookup. A reload has none and looks it up.
 */
let handedScan: { barcode: string; scan: ScanResolution } | null = null;

/** Story 353 — a match a label read fills in: a library row, or a product not yet a food. */
type LabelTarget = { kind: 'library'; food: FoodItem } | { kind: 'new'; food: NewFoodItem };

documentStyleSheet(themeStyles);
documentStyleSheet(bindingStyles);
documentStyleSheet(screenStyles);

/**
 * Story 422 — add to a day's slot (`/health/log/new/:date/:slot`, the add-food flow). The view is
 * the URL (reload-safe, Back steps through it):
 * - nothing: `<food-picker>` — the library, saved meals, Open Food Facts, and Scan;
 * - `?food=<id>`: `<line-set-editor mode=log-new>` holding that food as its one line (story 434);
 * - `?barcode=<code>`: the scan resolved (story 373) — a library food or an OFF product opens the
 *   same editor, a code nothing knows goes back to the picker with the offer to bind it (340, 342);
 * - `?meal=<id>`: `<line-set-editor mode=log-new>` on the meal's lines, to change before logging;
 * - `?estimate=1` (story 423): describe or photograph a meal; the estimate is queued and its review
 *   (`/health/estimates/:id`) replaces this step.
 * `bind=<code>` carries a binding the user agreed to across a pick. One `POST /logs` either way.
 * Label (423, story 338) photographs a nutrition table into `<food-editor mode=label-draft>`; the
 * food it proposes is created when the line is logged. A match with no energy value offers the
 * same read to fill it in (story 353). Neither is in the URL: the draft lives as long as the page.
 */
export class HealthLogNewScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private dateValue = '';
    private slotValue = '';
    private queryValue = new URLSearchParams();
    private readonly body = document.createElement('div');
    private readonly log = createComponentLogger('health-log-new-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    set date(value: string) { this.dateValue = value; }
    set slot(value: string) { this.slotValue = value; }
    set query(value: URLSearchParams) { this.queryValue = value; }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, `Add to ${this.slotValue}`, 'health', '/health');
        this.body.className = 'log-new';
        this.statusNodes.retryNode.addEventListener('click', () => void this.render());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.body);
        void this.render();
    }

    private get mealType(): MealType {
        if (!(MEAL_TYPES as readonly string[]).includes(this.slotValue)) throw new Error(`Unknown slot "${this.slotValue}" — expected one of ${MEAL_TYPES.join(', ')}.`);
        return this.slotValue as MealType;
    }

    private async render(): Promise<void> {
        return safeExec(this, this.log, async () => {
            const meal = this.queryValue.get('meal');
            const food = this.queryValue.get('food');
            const barcode = this.queryValue.get('barcode');
            const bind = this.queryValue.get('bind');
            if (meal) await this.showMeal(meal);
            else if (food) await this.showFood(food, bind);
            else if (barcode) await this.showScan(barcode, bind);
            else if (this.queryValue.get('estimate') === '1') this.showEstimate();
            else this.showPicker(null);
        });
    }

    // ── Picking ───────────────────────────────────────────────────────────

    /**
     * `deadEnd`: a scanned code nothing could answer (the picker's miss) — the next pick may
     * become its answer (340). Story 432: the picker scans; a found code lands on `?barcode=`, so
     * the line is reload-safe, carrying what the scan resolved to rather than looking it up again.
     */
    private showPicker(deadEnd: string | null): void {
        this.body.replaceChildren();
        const picker = document.createElement('food-picker') as FoodPicker;
        picker.setAttribute('meal-type', this.mealType);
        picker.setAttribute('meals', '');
        picker.setAttribute('actions', 'scan label estimate');
        picker.addEventListener(HEALTH_EVENTS.FOOD_PICK, (e: FoodPickEvent) => {
            const { entry, scanned, bind = null } = e.detail;
            if (scanned && entry.kind !== 'meal') {
                handedScan = {
                    barcode: scanned.barcode,
                    scan: entry.kind === 'food'
                        ? { kind: 'library', item: entry.item, pending: scanned.pending }
                        : { kind: 'product', product: entry.product, pending: scanned.pending },
                };
                this.go({ barcode: scanned.barcode });
            } else if (entry.kind === 'meal') this.go({ meal: entry.meal.id });
            else if (entry.kind === 'food') this.go({ food: entry.item.id, bind });
            else if (entry.product.barcode) this.go({ barcode: entry.product.barcode, bind });
            // An OFF result without a barcode cannot be found again from the URL.
            else this.setError(new Error(`"${entry.product.product_name}" has no barcode, so it cannot be opened — search the library or add it as a food.`));
        });
        picker.addEventListener(HEALTH_EVENTS.FOOD_PICK_ACTION, (e: FoodPickActionEvent) => {
            const { action } = e.detail;
            // A food read off a label is exactly what a dead-end code should mean (story 340).
            if (action === 'label') this.pickLabelPhoto(null, picker.pendingBind);
            // What was typed in search is where the description starts.
            else if (action === 'estimate') this.go({ estimate: '1', q: e.detail.query.trim() || null });
        });
        this.body.append(picker);
        picker.showMiss(deadEnd);
        picker.focusSearch();
    }

    private go(params: Record<string, string | null>): void {
        const query = new URLSearchParams();
        for (const [k, v] of Object.entries(params)) if (v) query.set(k, v);
        navigate(`${window.location.pathname}?${query}`);
    }

    // ── A food ────────────────────────────────────────────────────────────

    private async showFood(id: string, bind: string | null): Promise<void> {
        const food = await HealthService.findFoodItem(id);
        if (!food) throw new Error(`Food ${id} not found.`);
        this.showLine(foodLineView(food, defaultAmount(food), uuidv7()), bind, bind !== null);
    }

    private async showScan(barcode: string, bind: string | null): Promise<void> {
        const handed = handedScan?.barcode === barcode ? handedScan.scan : null;
        handedScan = null;
        const scan = handed ?? await resolveScannedBarcode(barcode, this.log);
        // A code matched by its in-store item code is a suggestion: offer to teach the exact code (369).
        const offer = bind ?? scan.pending;
        if (scan.kind === 'library') {
            this.showLine(foodLineView(scan.item, defaultAmount(scan.item), uuidv7()), offer, bind !== null);
            // Story 369: item codes are per retailer and collide across them — a suggestion to check.
            if (scan.item.matched_by === 'item_code') this.matchNote('Matched by product code — another package of this food. Check it is the same one.');
        } else if (scan.kind === 'product') {
            this.showLine(pickedLine({ kind: 'off', product: scan.product }), offer, bind !== null);
            // Story 337: found through its item code, the nutrition is another package's — say so.
            if (scan.product.matched_by === 'item_code') {
                this.matchNote(`Matched by product code (${scan.product.matched_barcode}) — this exact package wasn't found, so check the values.`);
            }
        } else {
            this.log.warn('barcode scan unresolved', {
                barcode, barcodeClass: inStoreItemCode(barcode) ? 'in_store' : 'gs1', library: scan.library, off: scan.off, status: scan.status,
            });
            this.showPicker(barcode);
        }
    }

    /** Under the line's title: a scan that matched through an item code, not the code itself. */
    private matchNote(text: string): void {
        const note = document.createElement('p');
        note.id = 'match-note';
        note.className = 'match-note';
        note.textContent = text;
        this.body.querySelector('line-set-editor')?.before(note);
    }

    /**
     * Story 434 — one food is a log of one line, in the same set editor as a meal: name, day, slot,
     * eaten at, the line (tap for its detail), Portion, + Add food, Log. `offer` a code to bind to it.
     */
    private showLine(view: LineView, offer: string | null, consented: boolean): void {
        this.body.replaceChildren();
        let consent = consented;
        if (offer) {
            const banner = document.createElement('barcode-binding-banner');
            banner.id = 'map-barcode-banner';
            banner.className = 'map-banner';
            banner.setAttribute('kind', 'offer');
            banner.setAttribute('barcode', offer);
            banner.toggleAttribute('consent', consented);
            banner.addEventListener(HEALTH_EVENTS.BIND_CONSENT_CHANGE, (e: BindConsentChangeEvent) => { consent = e.detail.consent; });
            this.body.append(banner);
        }
        const photo = this.newFoodPhoto(view);
        if (photo) this.body.append(photo.element);
        const editor = this.lineSetEditor({ name: '', lines: [view] }, (d) => {
            // The scanned food is still the log's first line: the code may be taught it.
            const first = d.lines[0]?.key === view.key;
            const lines = d.lines.map((l) => {
                const input = toLineInput(l);
                // A photo for the new food rides it, if that food is still here.
                const path = l.key === view.key ? photo?.path() ?? null : null;
                if (path && input.new_food_item) input.new_food_item = { ...input.new_food_item, image_path: path };
                return input;
            });
            return { lines, bind: first && offer && consent ? offer : null };
        }, photo?.uploaded);

        // Story 353: a match with no energy value logs as 0 kcal whatever else it has — offer to
        // read its label. A real 0 kcal product gets the offer too; it is an offer, not a redirect.
        const match = this.labelTarget(view);
        if (match && !(match.food.calories_per_base ?? 0)) {
            const read = document.createElement('button');
            read.type = 'button';
            read.className = 'label-offer';
            read.textContent = 'No calories here — read them off the label';
            read.addEventListener('click', () => this.pickLabelPhoto(match, offer && consent ? offer : null));
            this.body.insertBefore(read, editor);
        }
    }

    /**
     * Story 355 — a food this log will create, with no picture of its own or from Open Food Facts,
     * can be given one first. There is no row yet, so the upload is all or nothing and the path is
     * held to ride the new food. A library food's picture is its own page's (`/health/foods/:id`).
     */
    private newFoodPhoto(view: LineView): { element: PhotoControls; path: () => string | null; uploaded: () => Promise<void> } | null {
        if (!('new_food_item' in view.source)) return null;
        const food = view.source.new_food_item;
        const offPicture = food.raw_json ? Boolean((JSON.parse(food.raw_json) as { image_url?: string }).image_url) : false;
        if (food.image_path || offPicture) return null;
        const element = document.createElement('photo-controls') as PhotoControls;
        element.className = 'new-food-photo';
        element.setAttribute('scope', 'food');
        customElements.upgrade(element);
        element.show({ localRef: null, path: null, alt: view.name, editable: true });
        let path: string | null = null;
        let uploaded = Promise.resolve();
        let settle = () => {};
        element.addEventListener(HEALTH_EVENTS.PHOTO_UPLOADING, (e) => {
            if (e.detail.uploading) uploaded = new Promise((resolve) => { settle = resolve; });
            else settle();
        });
        element.addEventListener(HEALTH_EVENTS.PHOTO_PICKED, (e) => { e.stopPropagation(); path = e.detail.image_path; });
        element.addEventListener(HEALTH_EVENTS.PHOTO_REMOVED, (e) => { e.stopPropagation(); path = null; });
        return { element, path: () => path, uploaded: () => uploaded };
    }

    // ── A label ───────────────────────────────────────────────────────────

    /** The food a label read would fill in: the library row (updated) or the product (created). */
    private labelTarget(view: LineView): LabelTarget | null {
        if (view.basis.kind !== 'food') return null;
        if ('food_item_id' in view.source) return { kind: 'library', food: view.basis.food as FoodItem };
        if ('new_food_item' in view.source) return { kind: 'new', food: view.source.new_food_item };
        return null;
    }

    /** Ask for the photo inside the tap that asked for it — a picker opened later is blocked. */
    private pickLabelPhoto(target: LabelTarget | null, bind: string | null): void {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.setAttribute('capture', 'environment');
        input.addEventListener('change', () => {
            const file = input.files?.[0];
            if (file) void this.readLabel(file, target, bind);
        });
        input.click();
    }

    private async readLabel(file: File, target: LabelTarget | null, bind: string | null): Promise<void> {
        const before = [...this.body.childNodes];
        const reading = document.createElement('p');
        reading.className = 'label-reading screen-loading';
        reading.textContent = 'Reading the label…';
        this.body.replaceChildren(reading);
        let read: { result: LabelReadResult; problem: string | null };
        try {
            read = await readLabelPhoto(file);
        } catch (err) {
            // The photo is fine and retrying is the fix: back to where the read was asked for.
            this.log.warn('label read failed; the view it was asked from stands', { error: err instanceof Error ? err.message : String(err) });
            this.body.replaceChildren(...before);
            this.setError(err);
            return;
        }
        this.showLabelDraft(read.result, read.problem, target, bind);
    }

    /** The read, as a draft food to check; Use these values makes it the line to log. */
    private showLabelDraft(result: LabelReadResult, problem: string | null, target: LabelTarget | null, bind: string | null): void {
        this.clearStatus();
        this.body.replaceChildren();
        if (problem) {
            // Fail loud: the model's own words say whether to retake the photo or type it in.
            const note = document.createElement('p');
            note.className = 'label-problem';
            note.setAttribute('role', 'alert');
            note.textContent = `Could not read this label — fill it in by hand. ${problem}`;
            this.body.append(note);
        }
        const editor = document.createElement('food-editor') as FoodEditor;
        editor.setAttribute('mode', 'label-draft');
        customElements.upgrade(editor);
        editor.food = target ? { ...fillFromLabel(target.food, result.draft), ...(target.kind === 'library' ? { id: target.food.id } : {}) } : result.draft;
        editor.unread = problem ? [] : unreadLabels(result.unread);
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_SAVE, (e: FoodEditorSaveEvent) => {
            e.detail.respondWith = this.useLabelValues(e.detail.food, target, bind);
        });
        this.body.append(editor);
    }

    /** A library match is updated in place (it owns its code already); anything else is created when logged. */
    private async useLabelValues(food: NewFoodItem, target: LabelTarget | null, bind: string | null): Promise<void> {
        return safeExec(this, this.log, async () => {
            if (target?.kind === 'library') {
                const updated = await HealthService.updateFoodItem(target.food.id, food);
                this.showLine(foodLineView(updated, defaultAmount(updated), uuidv7()), bind, bind !== null);
                return;
            }
            const amount = defaultAmount({ default_serving_amount: food.default_serving_amount ?? null, serving_quantity: food.serving_quantity ?? null, base_amount: food.base_amount });
            this.showLine({ ...newFoodLineView(food, amount, uuidv7()), badge: target ? 'off' : 'label' }, bind, bind !== null);
        });
    }

    // ── An estimate ───────────────────────────────────────────────────────

    /**
     * Describe the meal, or photograph it, or both. The submit is stored on the device before any
     * network (story 221), so it survives being offline and the app closing; the review replaces
     * this step — authoring is finished once it is queued (story 291). What was typed is kept
     * across Back for the session (story 370).
     */
    private showEstimate(): void {
        this.body.replaceChildren();
        const form = document.createElement('form');
        form.className = 'estimate-form';
        const description = document.createElement('textarea');
        description.className = 'estimate-description';
        description.setAttribute('aria-label', 'Describe your meal');
        description.placeholder = 'e.g. 2 scrambled eggs with toast and butter, a glass of orange juice';
        const photoRow = document.createElement('div');
        photoRow.className = 'estimate-photo';
        const pick = document.createElement('button');
        pick.type = 'button';
        pick.className = 'estimate-photo-add';
        pick.textContent = '📷 Add a photo';
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/jpeg,image/png,image/webp';
        input.hidden = true;
        const preview = document.createElement('img');
        preview.className = 'estimate-photo-preview';
        preview.alt = 'Your meal';
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'estimate-photo-remove';
        remove.setAttribute('aria-label', 'Remove the photo');
        remove.textContent = '×';
        photoRow.append(pick, input, preview, remove);
        const submit = document.createElement('button');
        submit.type = 'submit';
        submit.className = 'estimate-submit';
        submit.textContent = '✨ Estimate';
        form.append(description, photoRow, submit);
        this.body.append(form);

        let photo: File | null = null;
        let previewUrl: string | null = null;
        const showPhoto = (file: File | null) => {
            photo = file;
            if (previewUrl) URL.revokeObjectURL(previewUrl);
            previewUrl = file ? URL.createObjectURL(file) : null;
            preview.hidden = !file;
            remove.hidden = !file;
            if (previewUrl) preview.src = previewUrl;
            else preview.removeAttribute('src');
        };
        const keep = () => saveAiEstimateDraft({ description: description.value, photo });
        const draft = readAiEstimateDraft();
        description.value = draft?.description || (this.queryValue.get('q') ?? '');
        showPhoto(draft?.photo ?? null);

        description.addEventListener('input', keep);
        pick.addEventListener('click', () => input.click());
        input.addEventListener('change', () => { showPhoto(input.files?.[0] ?? null); input.value = ''; keep(); });
        remove.addEventListener('click', () => { showPhoto(null); keep(); });
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const text = description.value.trim();
            if (!text && !photo) {
                description.focus();
                return;
            }
            void whileBusy(submit, () => this.submitEstimate(text, photo));
        });
        description.focus();
    }

    private async submitEstimate(description: string, photo: File | null): Promise<void> {
        return safeExec(this, this.log, async () => {
            const { enqueueEstimateSubmit } = await import('../../../services/offline/estimate-submit-store.js');
            const { shipPendingEstimateSubmits, requestEstimateSubmitSync } = await import('../../../services/offline/estimate-submit-shipping.js');
            const id = await enqueueEstimateSubmit({
                description: description || undefined,
                date: this.dateValue,
                meal_type: this.mealType,
                image: photo ? { blob: photo, filename: photo.name || 'meal.jpg' } : null,
            });
            clearAiEstimateDraft();
            navigate(`/health/estimates/${encodeURIComponent(id)}?pending=1`, { history: 'replace' });
            void shipPendingEstimateSubmits().catch((err) =>
                this.log.warn('estimate submit drain failed', { error: err instanceof Error ? err.message : String(err) }));
            void requestEstimateSubmitSync().catch(() => { /* falls back to the online / startup drain */ });
        });
    }

    // ── A meal ────────────────────────────────────────────────────────────

    private async showMeal(id: string): Promise<void> {
        const meal = await HealthService.getMeal(id);
        this.body.replaceChildren();
        this.lineSetEditor({ name: meal.name, lines: meal.ingredients.map(ingredientView), mealId: meal.id },
            (d) => ({ lines: d.lines.map(toLineInput), bind: null }));
    }

    /**
     * The set editor this screen logs from, with its add sheet, appended to the body. `prepare`
     * turns what was saved into the lines to log; `ready` is waited for first (a photo uploading).
     */
    private lineSetEditor(
        start: { name: string; lines: LineView[]; mealId?: string },
        prepare: (d: LineSetSaveEvent['detail']) => { lines: LineInput[]; bind: string | null },
        ready: () => Promise<void> = () => Promise.resolve(),
    ): LineSetEditor {
        const editor = document.createElement('line-set-editor') as LineSetEditor;
        editor.setAttribute('mode', 'log-new');
        customElements.upgrade(editor);
        editor.value = { name: start.name, date: this.dateValue, meal_type: this.mealType, time: nowHHMM(getAppTimeZone()) };
        editor.lines = start.lines;
        const add = document.createElement('line-add-dialog') as LineAddDialog;
        editor.addEventListener(HEALTH_EVENTS.LINE_ADD_REQUEST, () => add.open(this.mealType));
        add.addEventListener(HEALTH_EVENTS.LINE_PICKED, (e: LinePickedEvent) => {
            editor.addLine(e.detail.line);
            void safeExec(this, this.log, () => bindPickedBarcode(e.detail.line, e.detail.bind));
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_SAVE, (e: LineSetSaveEvent) => {
            const d = e.detail;
            // A photo still uploading is waited for: Log means "with the photo I just took".
            e.detail.respondWith = ready().then(() => {
                const { lines, bind } = prepare(d);
                return this.logLines(lines, {
                    consumedTime: d.time, date: d.date, mealType: d.meal_type, mealId: start.mealId, name: d.name.trim() || null, bind,
                });
            });
        });
        this.body.append(editor, add);
        return editor;
    }

    // ── Logging ───────────────────────────────────────────────────────────

    private async logLines(lines: LineInput[], opts: {
        consumedTime: string; bind: string | null; date?: string; mealType?: MealType; mealId?: string; name?: string | null;
    }): Promise<void> {
        const date = opts.date ?? this.dateValue;
        return safeExec(this, this.log, async () => {
            const created = await HealthService.createLog({
                id: uuidv7(),
                date,
                meal_type: opts.mealType ?? this.mealType,
                // Story 260: the HH:MM anchors on the log's day in the app zone; cleared logs unstamped.
                consumed_at: opts.consumedTime ? dateAndTimeToInstant(date, opts.consumedTime, getAppTimeZone()) : null,
                meal_id: opts.mealId ?? null,
                name: opts.name ?? null,
                lines,
            });
            if (opts.bind) await this.bindBarcode(created.lines[0]?.food_item_id ?? null, opts.bind);
            await exitFlow(`/health/day/${encodeURIComponent(date)}`);
        });
    }

    /** Stories 340/369: teach the scanned code the food it turned out to be. A failure leaves the log standing. */
    private async bindBarcode(foodItemId: string | null, barcode: string): Promise<void> {
        if (!foodItemId) return;
        try {
            await HealthService.mapFoodItemBarcode(foodItemId, barcode);
            this.log.debug('mapped unresolved barcode', { foodItemId, barcode });
        } catch (err) {
            this.log.warn('mapping an unresolved barcode failed; the log still stands', err);
        }
    }
}

if (!customElements.get('health-log-new-screen')) {
    customElements.define('health-log-new-screen', HealthLogNewScreen);
}
